// Custom UI fonts and icon sheet (spec 20 §2, §5) as one FT81x RAM_G image.
//
// font_data.h / font_data.inc are generated by tools/fonts/gen_fonts.py (`make fonts`) and
// committed. The image is uploaded verbatim to RAM_G at kRamGBase by the
// FT81x driver and by the simulator, which renders from the same bytes
// (alpha = nibble x 17). Per font: a 148-byte legacy font metric block
// (widths[128], format L4, stride, cell width, cell height, address of the
// cell of character 0) followed by L4 cells from `first` to 126; then the
// IconId cells (12 x 12 L4).
//
// Symbol codes (our own drawings, spec 20 §2.4): font 4 codes 24..31 are
// transport icon pairs (left half, right half): 24/25 pause, 26/27 play,
// 28/29 play pattern, 30/31 record. Font 5 codes 17..31: kSym* below.
#pragma once

#include <cstdint>

namespace ot {
namespace fontdata {

struct FontInfo {
    uint32_t metric;    // byte offset of the 148-byte metric block in kBlob
    uint32_t glyphs;    // byte offset of the cell of `first`
    uint8_t first;      // first character with a cell
    uint8_t w, h;       // cell size, px
    uint8_t stride;     // bytes per cell row
    uint8_t baseline;   // row below the ink of "H"
    uint8_t cap;        // cap height, px
};
struct IconSheet {
    uint32_t offset;
    uint8_t w, h, stride, count;
};

// Font 4 transport pairs and font 5 symbols.
constexpr char kSymPause[] = "\x18\x19";
constexpr char kSymPlay[] = "\x1a\x1b";
constexpr char kSymPlayPattern[] = "\x1c\x1d";
constexpr char kSymRecord[] = "\x1e\x1f";
enum SmallSymbol : uint8_t {
    kSymUp = 17, kSymDown, kSymLeft, kSymRight, kSymDot, kSymRing, kSymSquare, kSymBox,
    kSymCheck, kSymCross, kSymNote, kSymLoop, kSymPlus, kSymMinus, kSymEllipsis
};

#include "ui/fonts/font_data.h"

extern const uint8_t kBlob[kBlobSize];   // fonts.cpp (font_data.inc)

constexpr uint32_t kRamGEnd = kRamGBase + kBlobSize;
constexpr uint32_t kMetricBytes = 148;

// Font `role` 0..4 (kFont1..kFont5 - 1) of set 0..1; out of range -> set 0 / font 1.
inline const FontInfo& info(int set, int role) {
    return kFonts[(set == 1) ? 1 : 0][(role >= 0 && role < 5) ? role : 0];
}
// Pen advance of character `ch` (metric block width table, 0 if no glyph).
inline uint8_t advance(const FontInfo& f, uint8_t ch) { return ch < 128 ? kBlob[f.metric + ch] : 0; }
// Pointer to the L4 cell of `ch`, or nullptr outside first..126.
inline const uint8_t* cell(const FontInfo& f, uint8_t ch) {
    if (ch < f.first || ch > 126) return nullptr;
    return kBlob + f.glyphs + uint32_t(ch - f.first) * f.stride * f.h;
}
// RAM_G address of the cell of character 0 (BITMAP_SOURCE of the handle).
inline uint32_t sourceAddr(const FontInfo& f) {
    return kRamGBase + f.glyphs - uint32_t(f.first) * f.stride * f.h;
}

}  // namespace fontdata
}  // namespace ot
